import { existsSync } from 'node:fs';
import { fileURLToPath, URL } from 'node:url';
import react from '@vitejs/plugin-react';
import { defineConfig, type Plugin } from 'vite';

const AMPLIFY_OUTPUTS = fileURLToPath(new URL('./amplify_outputs.json', import.meta.url));

/**
 * `amplify_outputs.json` is generated by `npx ampx sandbox` and is gitignored,
 * so a fresh clone does not have it and Rollup fails to resolve the dynamic
 * import. The app already handles the file being absent at runtime — this just
 * gives the bundler an empty object to resolve to, so `npm run build` works
 * before the backend has been provisioned.
 */
function amplifyOutputsStub(): Plugin {
  const VIRTUAL = '\0virtual:amplify-outputs';
  return {
    name: 'preventai:amplify-outputs-stub',
    enforce: 'pre',
    resolveId(source) {
      if (!source.endsWith('amplify_outputs.json')) return null;
      return existsSync(AMPLIFY_OUTPUTS) ? null : VIRTUAL;
    },
    load(id) {
      if (id !== VIRTUAL) return null;
      return 'export default {};';
    },
    configResolved() {
      if (!existsSync(AMPLIFY_OUTPUTS)) {
        console.warn(
          '[PreventAI] amplify_outputs.json not found — building without an Amplify backend. ' +
            'Run `npx ampx sandbox` to provision it.'
        );
      }
    },
  };
}

/**
 * Deep links into the SPA (`/patient/my-plan`, `/clinician/patients/…`) are
 * not real files, so a static host returns 404 unless it is told to rewrite
 * unknown paths to `index.html`. On Amplify that is a console setting, which
 * cannot be committed to the repo.
 *
 * Emitting a copy of the shell as `404.html` means those links still load the
 * app on a host that has not been configured yet — Amplify serves it for
 * not-found paths, React reads `location.pathname` and routes correctly. The
 * response still carries a 404 status, so DEPLOY.md explains the one-time
 * rewrite rule that fixes it properly. This is the safety net, not the fix.
 */
function spaFallbackHtml(): Plugin {
  return {
    name: 'preventai:spa-fallback-html',
    apply: 'build',
    enforce: 'post',
    generateBundle(_options, bundle) {
      const shell = bundle['index.html'];
      if (shell && shell.type === 'asset') {
        this.emitFile({
          type: 'asset',
          fileName: '404.html',
          source: shell.source,
        });
      }
    },
  };
}

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [amplifyOutputsStub(), react(), spaFallbackHtml()],
  resolve: {
    alias: {
      '@': fileURLToPath(new URL('./src', import.meta.url)),
    },
  },
  optimizeDeps: {
    exclude: ['lucide-react'],
  },
});
